require_once __DIR__.'/global_brand_v704.php';

function pr560_enabled(): bool { return function_exists('setting_bool') ? setting_bool('property_v560_enabled', true) : true; }
function pr560_table(string $name): bool { try{$q=db()->prepare('SHOW TABLES LIKE ?');$q->execute([$name]);return (bool)$q->fetchColumn();}catch(Throwable $e){return false;} }
function pr560_tenant_id(): ?int { if(function_exists('tenant_id')){$v=(int)(tenant_id()?:0);return $v>0?$v:null;} return null; }
function pr560_city_id(): ?int { if(function_exists('tenant_city_id')){$v=(int)(tenant_city_id()?:0);return $v>0?$v:null;} if(function_exists('tenant_query_city_id')){$v=(int)tenant_query_city_id();return $v>0?$v:null;} return null; }
function pr560_json_decode($v,array $fallback=[]): array { if(is_array($v))return $v;$d=json_decode((string)$v,true);return is_array($d)?$d:$fallback; }
function pr560_json($v): string { return json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?:'{}'; }
function pr560_safe_url(string $v): string {$v=trim($v);if($v==='')return '';if(str_starts_with($v,'/'))return $v;return filter_var($v,FILTER_VALIDATE_URL)?$v:'';}
function pr560_money(float $v,bool $call=false): string { if($call)return 'Price on Call'; if($v>=10000000)return 'Rs '.rtrim(rtrim(number_format($v/10000000,2),'0'),'.').' Crore'; if($v>=100000)return 'Rs '.rtrim(rtrim(number_format($v/100000,2),'0'),'.').' Lakh'; return 'Rs '.number_format($v,0); }
function pr560_area(float $v,string $unit): string { return rtrim(rtrim(number_format($v,2),'0'),'.').' '.($unit?:'Marla'); }
function pr560_slug_base(string $s): string {$x=strtolower(trim((string)preg_replace('/[^a-z0-9]+/i','-',$s),'-'));return $x!==''?$x:'property';}
function pr560_cols(string $table): array { static $cache=[];if(isset($cache[$table]))return $cache[$table];try{$rows=db()->query('SHOW COLUMNS FROM `'.str_replace('`','',$table).'`')->fetchAll();$cache[$table]=array_column($rows,'Field');}catch(Throwable $e){$cache[$table]=[];}return $cache[$table]; }
function pr560_unique_slug(string $title,int $ignore=0): string {$base=pr560_slug_base($title);$slug=$base;$i=2;while(true){$q=db()->prepare('SELECT id FROM city_portal_items WHERE slug=?'.($ignore?' AND id<>'.(int)$ignore:'').' LIMIT 1');$q->execute([$slug]);if(!$q->fetchColumn())return $slug;$slug=$base.'-'.$i++;}}
function pr560_parse_price(string $s): float {$s=strtolower(str_replace([',','rs.','rs','pkr'],'',trim($s)));if($s==='')return 0;$mult=1;if(str_contains($s,'crore'))$mult=10000000;elseif(str_contains($s,'lakh'))$mult=100000;elseif(str_contains($s,'thousand')||preg_match('/\bk\b/',$s))$mult=1000;if(preg_match('/([0-9]+(?:\.[0-9]+)?)/',$s,$m))return (float)$m[1]*$mult;return 0;}
function pr560_parse_area(string $s): array {$s=trim($s);if($s==='')return [0,'Marla'];$unit='Marla';foreach(['Kanal','Marla','Sq Ft','Sq Yard','Acre'] as $u){if(stripos($s,$u)!==false){$unit=$u;break;}}if(preg_match('/([0-9]+(?:\.[0-9]+)?)/',$s,$m))return [(float)$m[1],$unit];return [0,$unit];}
function pr560_get_lock(string $key): bool {try{$q=db()->prepare('SELECT GET_LOCK(?,0)');$q->execute([$key]);return (int)$q->fetchColumn()===1;}catch(Throwable $e){return true;}}
function pr560_release_lock(string $key): void {try{$q=db()->prepare('SELECT RELEASE_LOCK(?)');$q->execute([$key]);}catch(Throwable $e){}}

function pr560_bootstrap_legacy(): void {
    static $done=false;if($done||!pr560_enabled()||!pr560_table('property_listing_meta_v560')||!pr560_table('city_portal_items'))return;$done=true;
    $lock='shahkotpk:property:v560:bootstrap:'.(string)(pr560_tenant_id()??0).':'.(string)(pr560_city_id()??0);if(!pr560_get_lock($lock))return;
    try{
        $where=["p.content_type='property'"];$params=[];if(function_exists('tenant_apply_city_filter'))tenant_apply_city_filter($where,$params,'p.city_id');
        $q=db()->prepare('SELECT p.* FROM city_portal_items p WHERE '.implode(' AND ',$where).' ORDER BY p.id LIMIT 1500');$q->execute($params);
        $ins=db()->prepare("INSERT IGNORE INTO property_listing_meta_v560(portal_item_id,tenant_id,city_id,owner_user_id,purpose,property_type,bedrooms,bathrooms,area_value,area_unit,price_value,price_period,approval_status,verified,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())");
        foreach($q->fetchAll() as $r){$m=pr560_json_decode($r['meta_json']??'{}');$cat=strtolower((string)($r['category']??''));$listing=strtolower((string)($m['listing_type']??$m['purpose']??$cat));$purpose=str_contains($listing,'rent')?'rent':(str_contains($listing,'lease')?'lease':'sale');$type=(string)($m['property_type']??'');if($type===''){$type='Property';foreach(['house'=>'House','plot'=>'Plot','shop'=>'Shop','office'=>'Office','apartment'=>'Apartment','flat'=>'Apartment','portion'=>'Portion','farm'=>'Farm House','warehouse'=>'Warehouse','commercial'=>'Commercial'] as $needle=>$label){if(str_contains($cat.' '.$listing,$needle)){$type=$label;break;}}}$price=(float)($r['price']??0);if($price<=0)$price=pr560_parse_price((string)($m['price']??''));[$av,$au]=pr560_parse_area((string)($m['area']??$m['area_text']??''));$ins->execute([(int)$r['id'],pr560_tenant_id(),(int)($r['city_id']??0)?:pr560_city_id(),(int)($r['created_by']??0)?:null,$purpose,$type,(int)($m['beds']??0),(int)($m['baths']??0),$av,$au,$price,$purpose==='rent'?'month':null,'approved',!empty($r['featured'])?1:0]);}
    }catch(Throwable $e){if(function_exists('runtime_log'))runtime_log('Property v5.6 legacy bootstrap skipped',$e);}finally{pr560_release_lock($lock);}
}

function pr560_listing_select(): string {
    return "SELECT p.*,c.name city_name,c.slug city_slug,b.name business_name,b.slug business_slug,m.*,p.id portal_item_id,p.title portal_title,p.slug portal_slug,p.summary portal_summary,p.description portal_description,p.category portal_category,p.image_url portal_image,p.status portal_status,p.featured portal_featured,p.latitude portal_latitude,p.longitude portal_longitude,p.address portal_address,p.phone portal_phone,p.whatsapp portal_whatsapp,p.map_url portal_map_url,ua.name agent_name,ua.phone agent_phone,ua.email agent_email,uo.name owner_name,pr.name project_name,pr.slug project_slug FROM city_portal_items p JOIN cities c ON c.id=p.city_id LEFT JOIN businesses b ON b.id=p.business_id LEFT JOIN property_listing_meta_v560 m ON m.portal_item_id=p.id LEFT JOIN users ua ON ua.id=m.agent_user_id LEFT JOIN users uo ON uo.id=m.owner_user_id LEFT JOIN property_projects_v560 pr ON pr.id=m.project_id";
}
function pr560_enrich(array $r): array {
    $r['id']=(int)($r['portal_item_id']??$r['id']??0);$r['title']=$r['portal_title']??$r['title']??'';$r['slug']=$r['portal_slug']??$r['slug']??'';$r['summary']=$r['portal_summary']??$r['summary']??'';$r['description']=$r['portal_description']??$r['description']??'';$r['category']=$r['portal_category']??$r['category']??'';$r['image_url']=$r['portal_image']??$r['image_url']??'';$r['status']=$r['portal_status']??$r['status']??'';$r['featured']=(int)($r['portal_featured']??$r['featured']??0);$r['latitude']=$r['portal_latitude']??$r['latitude']??null;$r['longitude']=$r['portal_longitude']??$r['longitude']??null;$r['address']=$r['portal_address']??$r['address']??'';$r['phone']=$r['portal_phone']??$r['phone']??'';$r['whatsapp']=$r['portal_whatsapp']??$r['whatsapp']??'';$r['map_url']=$r['portal_map_url']??$r['map_url']??'';$r['gallery']=pr560_json_decode($r['gallery_json']??'[]',[]);if(!$r['gallery']&&!empty($r['image_url']))$r['gallery']=[$r['image_url']];$r['features']=pr560_json_decode($r['features_json']??'[]',[]);$r['utilities']=pr560_json_decode($r['utilities_json']??'[]',[]);$r['price_value']=(float)($r['price_value']??$r['price']??0);return $r;
}
function pr560_listings(array $f=[],int $limit=24,int $offset=0,bool $admin=false): array {
    pr560_bootstrap_legacy();$where=["p.content_type='property'"];$p=[];
    if(!$admin){$where[]="p.status='published'";$where[]="COALESCE(m.approval_status,'approved')='approved'";}if(function_exists('tenant_apply_city_filter'))tenant_apply_city_filter($where,$p,'p.city_id');
    if(!empty($f['q'])){$where[]='(p.title LIKE ? OR p.summary LIKE ? OR p.description LIKE ? OR p.address LIKE ? OR m.property_type LIKE ?)';$l='%'.trim((string)$f['q']).'%';array_push($p,$l,$l,$l,$l,$l);}if(!empty($f['city_id'])){$where[]='p.city_id=?';$p[]=(int)$f['city_id'];}if(!empty($f['purpose'])){$where[]='m.purpose=?';$p[]=(string)$f['purpose'];}if(!empty($f['type'])){$where[]='m.property_type=?';$p[]=(string)$f['type'];}if(!empty($f['project'])){$where[]='m.project_id=?';$p[]=(int)$f['project'];}if(isset($f['beds'])&&(int)$f['beds']>0){$where[]='m.bedrooms>=?';$p[]=(int)$f['beds'];}if(isset($f['baths'])&&(int)$f['baths']>0){$where[]='m.bathrooms>=?';$p[]=(int)$f['baths'];}if(isset($f['min_price'])&&(float)$f['min_price']>0){$where[]='m.price_value>=?';$p[]=(float)$f['min_price'];}if(isset($f['max_price'])&&(float)$f['max_price']>0){$where[]='m.price_value<=?';$p[]=(float)$f['max_price'];}if(!empty($f['featured']))$where[]='p.featured=1';if(!empty($f['verified']))$where[]='m.verified=1';if(!empty($f['status'])&&$admin){$where[]='p.status=?';$p[]=(string)$f['status'];}
    $sort=(string)($f['sort']??'recommended');$order=match($sort){'price_low'=>'m.price_value ASC,p.id DESC','price_high'=>'m.price_value DESC,p.id DESC','area_high'=>'m.area_value DESC,p.id DESC','popular'=>'m.views DESC,m.inquiry_count DESC,p.id DESC','newest'=>'p.id DESC',default=>'p.featured DESC,m.verified DESC,(m.promoted_until>=NOW()) DESC,m.views DESC,p.id DESC'};
    $sql=pr560_listing_select().' WHERE '.implode(' AND ',$where).' ORDER BY '.$order.' LIMIT '.max(1,min(200,$limit)).' OFFSET '.max(0,$offset);try{$q=db()->prepare($sql);$q->execute($p);$rows=$q->fetchAll()?:[];return array_map('pr560_enrich',$rows);}catch(Throwable $e){if(function_exists('runtime_log'))runtime_log('Property v5.6 listing query failed',$e);return [];}
}
function pr560_listing(int|string $id,bool $admin=false): ?array {pr560_bootstrap_legacy();$field=(is_int($id)||ctype_digit((string)$id))?'p.id':'p.slug';$where=["p.content_type='property'","{$field}=?"];$p=[$id];if(!$admin){$where[]="p.status='published'";$where[]="COALESCE(m.approval_status,'approved')='approved'";}if(function_exists('tenant_apply_city_filter'))tenant_apply_city_filter($where,$p,'p.city_id');try{$q=db()->prepare(pr560_listing_select().' WHERE '.implode(' AND ',$where).' LIMIT 1');$q->execute($p);$r=$q->fetch();return $r?pr560_enrich($r):null;}catch(Throwable $e){return null;}}
function pr560_types(): array {return ['House','Plot','Apartment','Portion','Shop','Office','Commercial','Warehouse','Farm House','Room','Building','Land','Other'];}
function pr560_purposes(): array {return ['sale'=>'For Sale','rent'=>'For Rent','lease'=>'For Lease'];}
