function pr560_features_catalog(): array {return ['Corner','Park Facing','Main Boulevard','Gated Community','Garage','Servant Quarter','Store Room','Terrace','Balcony','Lift','CCTV','Security','Boundary Wall','Kitchen','Drawing Room','Dining Room','Lawn','Basement','Solar','Generator','Internet','Furnished'];}
function pr560_current_user_favorites(int $uid): array {try{$q=db()->prepare('SELECT property_id FROM property_favorites_v560 WHERE user_id=? ORDER BY id DESC');$q->execute([$uid]);return array_map('intval',array_column($q->fetchAll(),'property_id'));}catch(Throwable $e){return [];}}
function pr560_toggle_favorite(int $uid,int $pid): bool {$p=pr560_listing($pid);if(!$p)throw new RuntimeException('Property not found.');$q=db()->prepare('SELECT id FROM property_favorites_v560 WHERE user_id=? AND property_id=? LIMIT 1');$q->execute([$uid,$pid]);$id=(int)$q->fetchColumn();if($id){db()->prepare('DELETE FROM property_favorites_v560 WHERE id=?')->execute([$id]);db()->prepare('UPDATE property_listing_meta_v560 SET favorite_count=GREATEST(0,favorite_count-1) WHERE portal_item_id=?')->execute([$pid]);return false;}db()->prepare('INSERT IGNORE INTO property_favorites_v560(user_id,property_id,created_at) VALUES(?,?,NOW())')->execute([$uid,$pid]);db()->prepare('UPDATE property_listing_meta_v560 SET favorite_count=favorite_count+1 WHERE portal_item_id=?')->execute([$pid]);return true;}
