function pr560_track_view_once(int $pid): void {$k='pr560_viewed_'.$pid;if(!empty($_SESSION[$k]))return;$_SESSION[$k]=time();pr560_track($pid,'view');}
function pr560_create_lead(int $pid,array $data): int {$p=pr560_listing($pid);if(!$p)throw new RuntimeException('Property not found.');$u=current_user();if(!$u&&function_exists('setting_bool')&&!setting_bool('property_v560_guest_inquiries',true))throw new RuntimeException('Please sign in to contact this property.');$name=trim((string)($data['name']??($u['name']??'')));$phone=trim((string)($data['phone']??($u['phone']??'')));$email=trim((string)($data['email']??($u['email']??'')));if($name===''||$phone==='')throw new RuntimeException('Name and phone are required.');$type=in_array(($data['lead_type']??'inquiry'),['inquiry','call_request','whatsapp','visit','offer'],true)?(string)$data['lead_type']:'inquiry';db()->prepare("INSERT INTO property_leads_v560(property_id,user_id,name,phone,email,lead_type,message,budget,status,assigned_to,source,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,'new',?,'website',NOW(),NOW())")->execute([$pid,(int)($u['id']??0)?:null,$name,$phone,$email,$type,trim((string)($data['message']??'')),($data['budget']??'')!==''?(float)$data['budget']:null,(int)($p['agent_user_id']??0)?:null]);$id=(int)db()->lastInsertId();db()->prepare('UPDATE property_listing_meta_v560 SET inquiry_count=inquiry_count+1 WHERE portal_item_id=?')->execute([$pid]);pr560_track($pid,'inquiry',['lead_type'=>$type]);return $id;}
function pr560_create_visit(int $pid,array $data): int {$p=pr560_listing($pid);if(!$p)throw new RuntimeException('Property not found.');$u=current_user();if(!$u&&function_exists('setting_bool')&&!setting_bool('property_v560_guest_inquiries',true))throw new RuntimeException('Please sign in to request a property visit.');$name=trim((string)($data['name']??($u['name']??'')));$phone=trim((string)($data['phone']??($u['phone']??'')));$date=trim((string)($data['visit_date']??''));$time=trim((string)($data['visit_time']??''));if($name===''||$phone===''||$date==='')throw new RuntimeException('Name, phone and visit date are required.');$when=date('Y-m-d H:i:s',strtotime($date.' '.($time?:'12:00')));db()->prepare("INSERT INTO property_visits_v560(property_id,user_id,name,phone,scheduled_at,note,status,assigned_to,created_at,updated_at) VALUES(?,?,?,?,?,?,'requested',?,NOW(),NOW())")->execute([$pid,(int)($u['id']??0)?:null,$name,$phone,$when,trim((string)($data['note']??'')),(int)($p['agent_user_id']??0)?:null]);$id=(int)db()->lastInsertId();pr560_track($pid,'visit');return $id;}
function pr560_projects(int $limit=200,bool $active=true): array {$where=[];$p=[];if($active)$where[]="pr.status='active'";if(($tid=pr560_tenant_id())!==null){$where[]='(pr.tenant_id IS NULL OR pr.tenant_id=?)';$p[]=$tid;}if(($cid=pr560_city_id())!==null){$where[]='(pr.city_id IS NULL OR pr.city_id=?)';$p[]=$cid;}try{$sql="SELECT pr.*,(SELECT COUNT(*) FROM property_listing_meta_v560 m JOIN city_portal_items p2 ON p2.id=m.portal_item_id WHERE m.project_id=pr.id AND p2.status='published') listing_count FROM property_projects_v560 pr".($where?' WHERE '.implode(' AND ',$where):'')." ORDER BY pr.featured DESC,pr.name LIMIT ".max(1,min(500,$limit));$q=db()->prepare($sql);$q->execute($p);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
