function pr560_agents(int $limit=200): array {$where=['(ap.id IS NOT NULL OR EXISTS(SELECT 1 FROM property_listing_meta_v560 mm WHERE mm.agent_user_id=u.id))'];$p=[];if(($tid=pr560_tenant_id())!==null){$where[]='(ap.tenant_id IS NULL OR ap.tenant_id=?)';$p[]=$tid;}try{$sql="SELECT u.id,u.name,u.email,u.phone,ap.agency_name,ap.license_no,ap.verified,ap.bio,ap.service_areas,(SELECT COUNT(*) FROM property_listing_meta_v560 m JOIN city_portal_items p2 ON p2.id=m.portal_item_id WHERE m.agent_user_id=u.id AND p2.status='published') listing_count FROM users u LEFT JOIN property_agent_profiles_v560 ap ON ap.user_id=u.id WHERE ".implode(' AND ',$where)." ORDER BY ap.verified DESC,u.name LIMIT ".max(1,min(500,$limit));$q=db()->prepare($sql);$q->execute($p);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function pr560_upload_many(string $field): array {$out=[];if(empty($_FILES[$field])||!is_array($_FILES[$field])||empty($_FILES[$field]['name']))return $out;$f=$_FILES[$field];$count=is_array($f['name'])?count($f['name']):1;for($i=0;$i<$count;$i++){$one=['name'=>is_array($f['name'])?$f['name'][$i]:$f['name'],'type'=>is_array($f['type'])?$f['type'][$i]:$f['type'],'tmp_name'=>is_array($f['tmp_name'])?$f['tmp_name'][$i]:$f['tmp_name'],'error'=>is_array($f['error'])?$f['error'][$i]:$f['error'],'size'=>is_array($f['size'])?$f['size'][$i]:$f['size']];if((int)$one['error']!==UPLOAD_ERR_OK)continue;try{if(function_exists('store_upload_image')){$u=store_upload_image($one);if($u)$out[]=(string)$u;}}catch(Throwable $e){}}return array_values(array_unique($out));}
function pr560_save_listing(array $d,int $actorId,bool $admin=false): int {
