    $legacyMeta=['listing_type'=>$purpose==='rent'?'For Rent':($purpose==='lease'?'For Lease':'For Sale'),'property_type'=>$type,'area_text'=>pr560_area($area,$unit),'area'=>pr560_area($area,$unit),'beds'=>(string)(int)($d['bedrooms']??0),'baths'=>(string)(int)($d['bathrooms']??0),'price'=>pr560_money($price,!empty($d['price_on_call']))];
    $base=['content_type'=>'property','city_id'=>$city,'business_id'=>(int)($d['business_id']??0)?:null,'title'=>$title,'slug'=>$slug,'summary'=>trim((string)($d['summary']??'')),'description'=>trim((string)($d['description']??'')),'category'=>$type.' '.($purpose==='rent'?'for Rent':($purpose==='lease'?'for Lease':'for Sale')),'image_url'=>$image,'image'=>$image,'featured'=>!empty($d['featured'])?1:0,'sort_order'=>(int)($d['sort_order']??50),'status'=>$status,'meta_json'=>pr560_json($legacyMeta),'created_by'=>$old['created_by']??$actorId,'latitude'=>($d['latitude']??'')!==''?(float)$d['latitude']:null,'longitude'=>($d['longitude']??'')!==''?(float)$d['longitude']:null,'address'=>trim((string)($d['address']??'')),'map_url'=>pr560_safe_url((string)($d['map_url']??'')),'phone'=>trim((string)($d['phone']??'')),'whatsapp'=>trim((string)($d['whatsapp']??'')),'price'=>$price];$cols=pr560_cols('city_portal_items');$base=array_intersect_key($base,array_flip($cols));
    if($id){$sets=[];$vals=[];foreach($base as $k=>$v){if($k==='created_by'||$k==='content_type')continue;$sets[]='`'.$k.'`=?';$vals[]=$v;}if(in_array('updated_at',$cols,true))$sets[]='updated_at=NOW()';$vals[]=$id;db()->prepare('UPDATE city_portal_items SET '.implode(',',$sets).' WHERE id=?')->execute($vals);$pid=$id;}else{$keys=array_keys($base);$vals=array_values($base);if(in_array('created_at',$cols,true)){$keys[]='created_at';}$sql='INSERT INTO city_portal_items('.implode(',',array_map(fn($x)=>'`'.$x.'`',$keys)).') VALUES('.implode(',',array_fill(0,count($vals),'?')).(in_array('created_at',$cols,true)?',NOW()':'').')';db()->prepare($sql)->execute($vals);$pid=(int)db()->lastInsertId();}
    $features=array_values(array_unique(array_filter(array_map('trim',(array)($d['features']??[])))));$utilities=array_values(array_unique(array_filter(array_map('trim',(array)($d['utilities']??[])))));$meta=[pr560_tenant_id(),$city,(int)($d['owner_user_id']??($old['owner_user_id']??$actorId))?:$actorId,(int)($d['agent_user_id']??0)?:null,(int)($d['project_id']??0)?:null,$purpose,$type,trim((string)($d['subtype']??'')),trim((string)($d['condition_status']??'')),max(0,(int)($d['bedrooms']??0)),max(0,(int)($d['bathrooms']??0)),$area,$unit,max(0,(float)($d['covered_area']??0)),trim((string)($d['covered_area_unit']??$unit)),$price,trim((string)($d['price_period']??($purpose==='rent'?'month':''))),!empty($d['price_on_call'])?1:0,!empty($d['price_negotiable'])?1:0,max(0,(int)($d['floor_no']??0)),max(0,(int)($d['total_floors']??0)),max(0,(int)($d['year_built']??0)),max(0,(int)($d['parking_spaces']??0)),trim((string)($d['furnishing']??'')),trim((string)($d['possession_status']??'')),($d['possession_date']??'')?:null,!empty($d['installment_available'])?1:0,max(0,(float)($d['down_payment']??0)),max(0,(float)($d['monthly_installment']??0)),pr560_json($features),pr560_json($utilities),pr560_json($gallery),pr560_safe_url((string)($d['video_url']??'')),pr560_safe_url((string)($d['virtual_tour_url']??'')),pr560_safe_url((string)($d['floor_plan_url']??'')),trim((string)($d['reference_no']??'')),trim((string)($d['listed_by']??'owner')),!empty($d['verified'])?1:0,$approval,trim((string)($d['seo_title']??'')),trim((string)($d['seo_description']??''))];
    db()->prepare("INSERT INTO property_listing_meta_v560(portal_item_id,tenant_id,city_id,owner_user_id,agent_user_id,project_id,purpose,property_type,subtype,condition_status,bedrooms,bathrooms,area_value,area_unit,covered_area,covered_area_unit,price_value,price_period,price_on_call,price_negotiable,floor_no,total_floors,year_built,parking_spaces,furnishing,possession_status,possession_date,installment_available,down_payment,monthly_installment,features_json,utilities_json,gallery_json,video_url,virtual_tour_url,floor_plan_url,reference_no,listed_by,verified,approval_status,seo_title,seo_description,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW()) ON DUPLICATE KEY UPDATE tenant_id=VALUES(tenant_id),city_id=VALUES(city_id),owner_user_id=VALUES(owner_user_id),agent_user_id=VALUES(agent_user_id),project_id=VALUES(project_id),purpose=VALUES(purpose),property_type=VALUES(property_type),subtype=VALUES(subtype),condition_status=VALUES(condition_status),bedrooms=VALUES(bedrooms),bathrooms=VALUES(bathrooms),area_value=VALUES(area_value),area_unit=VALUES(area_unit),covered_area=VALUES(covered_area),covered_area_unit=VALUES(covered_area_unit),price_value=VALUES(price_value),price_period=VALUES(price_period),price_on_call=VALUES(price_on_call),price_negotiable=VALUES(price_negotiable),floor_no=VALUES(floor_no),total_floors=VALUES(total_floors),year_built=VALUES(year_built),parking_spaces=VALUES(parking_spaces),furnishing=VALUES(furnishing),possession_status=VALUES(possession_status),possession_date=VALUES(possession_date),installment_available=VALUES(installment_available),down_payment=VALUES(down_payment),monthly_installment=VALUES(monthly_installment),features_json=VALUES(features_json),utilities_json=VALUES(utilities_json),gallery_json=VALUES(gallery_json),video_url=VALUES(video_url),virtual_tour_url=VALUES(virtual_tour_url),floor_plan_url=VALUES(floor_plan_url),reference_no=VALUES(reference_no),listed_by=VALUES(listed_by),verified=VALUES(verified),approval_status=VALUES(approval_status),seo_title=VALUES(seo_title),seo_description=VALUES(seo_description),updated_at=NOW()") ->execute(array_merge([$pid],$meta));return $pid;
}
function pr560_admin_stats(): array {$s=['total'=>0,'published'=>0,'pending'=>0,'featured'=>0,'verified'=>0,'views'=>0,'leads'=>0,'visits'=>0];try{$where=["p.content_type='property'"];$pa=[];if(function_exists('tenant_apply_city_filter'))tenant_apply_city_filter($where,$pa,'p.city_id');$q=db()->prepare("SELECT COUNT(*) total,SUM(p.status='published') published,SUM(COALESCE(m.approval_status,'approved')='pending') pending,SUM(p.featured=1) featured,SUM(COALESCE(m.verified,0)=1) verified,SUM(COALESCE(m.views,0)) views FROM city_portal_items p LEFT JOIN property_listing_meta_v560 m ON m.portal_item_id=p.id WHERE ".implode(' AND ',$where));$q->execute($pa);$s=array_merge($s,$q->fetch()?:[]);$city=pr560_city_id();if($city){$q=db()->prepare("SELECT COUNT(*) FROM property_leads_v560 l JOIN city_portal_items p ON p.id=l.property_id WHERE p.city_id=? AND l.created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)");$q->execute([$city]);$s['leads']=(int)$q->fetchColumn();$q=db()->prepare("SELECT COUNT(*) FROM property_visits_v560 v JOIN city_portal_items p ON p.id=v.property_id WHERE p.city_id=? AND v.scheduled_at>=CURDATE()");$q->execute([$city]);$s['visits']=(int)$q->fetchColumn();}else{$s['leads']=(int)db()->query("SELECT COUNT(*) FROM property_leads_v560 WHERE created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)")->fetchColumn();$s['visits']=(int)db()->query("SELECT COUNT(*) FROM property_visits_v560 WHERE scheduled_at>=CURDATE()")->fetchColumn();}}catch(Throwable $e){}return $s;}
function pr560_leads(int $limit=200): array {try{$city=pr560_city_id();$sql="SELECT l.*,p.title property_title,p.slug property_slug,u.name assigned_name FROM property_leads_v560 l JOIN city_portal_items p ON p.id=l.property_id LEFT JOIN users u ON u.id=l.assigned_to".($city?' WHERE p.city_id=?':'')." ORDER BY l.id DESC LIMIT ".max(1,min(1000,$limit));$q=db()->prepare($sql);$q->execute($city?[$city]:[]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function pr560_visits(int $limit=200): array {try{$city=pr560_city_id();$sql="SELECT v.*,p.title property_title,p.slug property_slug,u.name assigned_name FROM property_visits_v560 v JOIN city_portal_items p ON p.id=v.property_id LEFT JOIN users u ON u.id=v.assigned_to".($city?' WHERE p.city_id=?':'')." ORDER BY v.scheduled_at DESC LIMIT ".max(1,min(1000,$limit));$q=db()->prepare($sql);$q->execute($city?[$city]:[]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function pr560_my_listings(int $uid): array {pr560_bootstrap_legacy();try{$q=db()->prepare(pr560_listing_select()." WHERE p.content_type='property' AND (m.owner_user_id=? OR m.agent_user_id=?) ORDER BY p.id DESC LIMIT 300");$q->execute([$uid,$uid]);return array_map('pr560_enrich',$q->fetchAll()?:[]);}catch(Throwable $e){return [];}}

function pr560_public_header(string $title='Property Pro',string $description='Buy, sell and rent property locally.'): void {global $config;$brand=function_exists('gb704_brand_name')?gb704_brand_name('ShahkotPK'):(function_exists('tenant_brand')?tenant_brand('site_name','ShahkotPK'):($config['app_name']??'ShahkotPK'));$csrf=csrf_token();$logo=function_exists('gb704_picture')?gb704_picture('property',$brand):'';$brandMarkup=$logo!==''?$logo.'<span class="gb704-module-label">Property</span>':'<span class="pr560-logo">⌂</span><span>'.e($brand).'</span>';echo '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="'.e($csrf).'"><title>'.e($title).' - '.e($brand).'</title><meta name="description" content="'.e($description).'"><link rel="stylesheet" href="/assets/property-pro-5.6.0.css?v=560">'.(function_exists('gb704_asset_tag')?gb704_asset_tag():'').'<script defer src="/assets/property-pro-5.6.0.js?v=560"></script></head><body class="pr560-body"><header class="pr560-top"><nav class="pr560-nav"><a class="pr560-brand gb704-brand" href="/">'.$brandMarkup.'</a><div class="pr560-navlinks"><a href="/property.php">Properties</a><a href="/property.php?purpose=sale">Buy</a><a href="/property.php?purpose=rent">Rent</a><a href="/my-properties.php">My Property</a><a class="pr560-post" href="/property-submit.php">＋ Post Property</a></div></nav></header>'; }
function pr560_public_footer(): void {echo '<div class="pr560-float-compare" data-pr-compare-tray><b><span data-pr-compare-count>0</span> selected</b><button type="button" data-pr-compare-go>Compare</button></div><footer style="background:#07182c;color:#9eb2cb;padding:34px 0;margin-top:30px"><div class="pr560-shell" style="display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap"><div><b style="color:#fff">ShahkotPK Property Pro</b><div>Local property discovery, inquiries and agent tools.</div></div><div><a style="color:#d8e7fa;text-decoration:none" href="/property-submit.php">Post Property</a> · <a style="color:#d8e7fa;text-decoration:none" href="/my-properties.php">My Dashboard</a></div></div></footer></body></html>';}
function pr560_image_style(string $url): string {return $url!==''?' style="background-image:url(\''.e($url).'\')"':'';}
function pr560_property_card(array $p,array $fav=[]): void {$id=(int)$p['id'];$liked=in_array($id,$fav,true);$period=$p['price_period']?'/'.$p['price_period']:'';echo '<article class="pr560-card"><a class="pr560-photo" href="/property.php?slug='.urlencode((string)$p['slug']).'"'.pr560_image_style((string)$p['image_url']).'><div class="pr560-badges"><span class="pr560-badge blue">'.e(strtoupper((string)$p['purpose'])).'</span>'.(!empty($p['verified'])?'<span class="pr560-badge green">VERIFIED</span>':'').(!empty($p['featured'])?'<span class="pr560-badge orange">FEATURED</span>':'').'</div></a><button class="pr560-card-fav '.($liked?'is-active':'').'" data-pr-favorite="'.$id.'" aria-label="Favorite">'.($liked?'♥':'♡').'</button><div class="pr560-card-copy"><small>'.e((string)$p['property_type']).' · '.e(pr560_area((float)$p['area_value'],(string)$p['area_unit'])).'</small><h3><a href="/property.php?slug='.urlencode((string)$p['slug']).'">'.e((string)$p['title']).'</a></h3><div class="pr560-price"><b>'.e(pr560_money((float)$p['price_value'],!empty($p['price_on_call']))).'</b><span>'.e($period).'</span></div><div class="pr560-facts"><i>🛏 '.(int)$p['bedrooms'].' Beds</i><i>🛁 '.(int)$p['bathrooms'].' Baths</i><i>▱ '.e(pr560_area((float)$p['area_value'],(string)$p['area_unit'])).'</i></div><div class="pr560-location">⌖ '.e((string)($p['address']?:$p['city_name'])).'</div><div style="display:flex;gap:7px;margin-top:12px"><a class="pr560-btn secondary" style="flex:1;padding:9px" href="/property.php?slug='.urlencode((string)$p['slug']).'">View Details</a><button class="pr560-btn secondary" style="padding:9px 11px;border:0" data-pr-compare="'.$id.'">⇄</button></div></div></article>';}
